# Generate web/server_conf.js: a header of plain variables, then the
# body from web/server_conf.body.js.
#
# This replaced passing settings in the environment. On macOS the server
# is daemonized through launchd, and the plist rampart writes carries
# only HOME and PATH -- every other variable is dropped, so a server
# started with an address came up on loopback and reported the address
# it had been asked for. A generated file has no such gap: what the
# server reads is what is on disk, on every platform.
#
# The header variables are ordinary globals, so the app modules see them
# too; that is how lib/tools.js gets the citation base.
#
# Sourced by setup.sh and servers.sh, which set HERE and WEB first.

# write_server_conf ADDR PORT BASE DATA ZIM
write_server_conf() {
    local addr="$1" port="$2" base="$3" data="$4" zim="$5"
    local body="$WEB/server_conf.body.js"
    local out="$WEB/server_conf.js"

    [ -r "$body" ] || { echo "missing $body" >&2; return 1; }
    # "request-host" is how the stored config spells "no fixed host";
    # the code wants an empty string for that.
    [ "$base" = "request-host" ] && base=""

    {
        echo "#!/usr/bin/env rampart"
        echo "/* Generated by setup.sh on $(date '+%Y-%m-%d %H:%M:%S')."
        echo " * Re-run ./setup.sh, or ./servers.sh -H ADDR -p PORT, to change"
        echo " * these. Everything below comes from web/server_conf.body.js,"
        echo " * which is the file to edit for anything else. */"
        echo "var confAddr    = \"$addr\";   /* \"localhost\", an address, or \"all\" */"
        echo "var confPort    = $port;"
        echo "var confBase    = \"$base\";   /* citation links; \"\" = each client's host */"
        # In-tree paths are emitted as confPath(...) so the whole
        # directory can be moved or renamed without an edit. A data or
        # archive directory somewhere else (DATA=/big/disk) cannot be
        # derived, so that one is written out literally.
        if [ "$data" = "$HERE/build" ]; then
            echo "var confData    = confPath(\"build\");   /* moves with this directory */"
        else
            echo "var confData    = \"$data\";"
        fi
        if [ "$zim" = "$HERE/zim" ]; then
            echo "var confZim     = confPath(\"zim\");"
        else
            echo "var confZim     = \"$zim\";"
        fi
        echo "var confZimBase = \"\";        /* set only if kiwix is on another host */"
        echo "var confKiwix   = \"\";        /* local kiwix-serve; \"\" = 127.0.0.1:8098 */"
        echo
        cat "$body"
    } > "$out.tmp" || { rm -f "$out.tmp"; return 1; }
    mv -f "$out.tmp" "$out"
    chmod +x "$out"
}
